import java.lang.reflect.*;
import java.util.*;

interface Account { void deposit(int x); void withdraw(int x); String info(); }
class AccountImpl implements Account {
    public void deposit(int x) { System.out.println("  deposit " + x); }
    public void withdraw(int x) { System.out.println("  withdraw " + x); }
    public String info() { return "account"; }
}
class AopHandler implements InvocationHandler {
    Object target; Set<String> matched;
    AopHandler(Object t, Set<String> m) { target = t; matched = m; }
    public Object invoke(Object p, Method m, Object[] args) throws Throwable {
        if (matched.contains(m.getName())) {
            System.out.println("[AOP] before " + m.getName());
            Object r = m.invoke(target, args);
            System.out.println("[AOP] after " + m.getName());
            return r;
        }
        return m.invoke(target, args);
    }
}
public class Main {
    public static void main(String[] a) throws Exception {
        // 切点：只对事务方法 deposit/withdraw 织入，info 不过滤
        Set<String> pc = new HashSet<>(Arrays.asList("deposit", "withdraw"));
        Account proxy = (Account) Proxy.newProxyInstance(Account.class.getClassLoader(),
            new Class[]{Account.class}, new AopHandler(new AccountImpl(), pc));
        proxy.deposit(100);
        proxy.withdraw(30);
        System.out.println("info -> " + proxy.info());
    }
}
